package io.clipbridge.android;
import android.app.*;
import android.content.*;
import android.content.pm.*;
import android.graphics.Bitmap;
import android.net.Uri;
import android.os.*;
import android.provider.MediaStore;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.security.*;
import java.util.*;
public final class MediaSmokeRunner extends Instrumentation {
    private final Uri provider=Uri.parse("content://io.clipbridge.android.bridge");private Context context;private final List<String> pairs=new ArrayList<>();private final List<Uri> rows=new ArrayList<>();private final List<Activity> activities=new ArrayList<>();private String previousState;private int passed;private boolean touched;
    public void onCreate(Bundle arguments){super.onCreate(arguments);start();}
    private void check(boolean value,String name){if(!value)throw new AssertionError(name);passed++;Bundle b=new Bundle();b.putString("stream","PASS "+name+"\n");sendStatus(0,b);}
    private Bundle call(String method,String arg,Bundle extras){return context.getContentResolver().call(provider,method,arg,extras);}
    private String id(){return UUID.randomUUID().toString().replace("-","");}
    private String secret(){byte[] bytes=new byte[32];new SecureRandom().nextBytes(bytes);return java.util.Base64.getEncoder().encodeToString(bytes);}
    private JSONObject config(String pair)throws Exception{return new JSONObject().put("server","https://127.0.0.1:19443/").put("pair",pair).put("device",id()).put("peer",id()).put("token",secret()).put("key",secret()).put("transport","webdav").put("username","qa").put("password","test-only-password");}
    private Bundle identity(JSONObject config)throws Exception{Bundle b=new Bundle();b.putString("pair",config.getString("pair"));b.putString("device",config.getString("device"));return b;}
    private JSONObject item(String id)throws Exception{JSONArray array=new JSONObject(call("attachment-load",null,null).getString("state")).getJSONArray("incoming");for(int i=0;i<array.length();i++)if(array.getJSONObject(i).getJSONObject("offer").getString("id").equals(id))return array.getJSONObject(i);return null;}
    private void await(java.util.concurrent.Callable<Boolean> ready)throws Exception{long end=System.currentTimeMillis()+25000;while(System.currentTimeMillis()<end){if(ready.call())return;Thread.sleep(200);}throw new AssertionError("Timed out waiting for Android behavior");}
    private Activity launch(String name,Intent extra){Intent intent=extra==null?new Intent():extra;intent.setClassName(context,name).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);Activity activity=startActivitySync(intent);activities.add(activity);waitForIdleSync();return activity;}
    private int nid(String id){return 10000+(id.hashCode()&0x3fffffff);}
    public void onStart(){Bundle result=new Bundle();boolean ok=false;try{
        if(!"ranchu".equals(Build.HARDWARE)&&!"goldfish".equals(Build.HARDWARE))throw new AssertionError("Run smoke tests only on an emulator");context=getTargetContext();if(new JSONArray(call("profiles",null,null).getString("profiles")).length()!=0)throw new AssertionError("Use a clean dedicated emulator");touched=true;previousState=call("attachment-load",null,null).getString("state");String a=id(),b=id(),peer=id();pairs.add(a);pairs.add(b);JSONObject ca=config(a),cb=config(b);call("import",ca.toString(),null);call("import",cb.toString(),null);
        Bundle toggle=new Bundle();toggle.putBoolean("enabled",false);call("toggle",a,toggle);check(!call("load",a,null).containsKey("config")&&call("load",b,null).containsKey("config"),"profile switches are independent");toggle.putBoolean("enabled",true);call("toggle",a,toggle);
        for(JSONObject c:new JSONObject[]{ca,cb}){Bundle metrics=identity(c);metrics.putString("peerIdentity",peer);metrics.putString("peerName","QA Computer");call("metrics",null,metrics);}
        long clock=call("new-event",null,null).getLong("clock");String event=id();Bundle seenA=identity(ca);seenA.putString("origin",peer);seenA.putLong("eventClock",clock);Bundle seenB=identity(cb);seenB.putString("origin",peer);seenB.putLong("eventClock",clock);
        check(call("seen",event,seenA).getBoolean("first")&&!call("seen",event,seenB).getBoolean("first"),"same event arriving over another config is received once");seenB.putLong("eventClock",clock+1);check(call("seen",id(),seenB).getBoolean("first"),"new cross-route event accepted");check(!call("seen",id(),seenA).getBoolean("first"),"older cross-route event cannot overwrite new content");
        Bundle saved=identity(ca);saved.putByteArray("state",new JSONObject().put("clock",1).put("winner",ca.getString("device")).toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));call("save",null,saved);call("delete",a,null);check(call("load",b,null).containsKey("config"),"deleting one profile preserves another");call("import",ca.toString(),null);check(new JSONObject(new String(call("load",a,null).getByteArray("state"),java.nio.charset.StandardCharsets.UTF_8)).getLong("clock")==1,"reimport preserves replay counter");Bundle metrics=identity(ca);metrics.putString("peerIdentity",peer);metrics.putString("peerName","QA Computer");call("metrics",null,metrics);
        PackageManager pm=context.getPackageManager();check(pm.queryIntentActivities(new Intent(Intent.ACTION_SEND).setType("image/png").setPackage(context.getPackageName()),PackageManager.MATCH_DEFAULT_ONLY).stream().anyMatch(x->x.activityInfo.name.endsWith("ShareActivity")),"image share target registered");check(pm.queryIntentActivities(new Intent(Intent.ACTION_SEND_MULTIPLE).setType("application/octet-stream").setPackage(context.getPackageName()),PackageManager.MATCH_DEFAULT_ONLY).stream().anyMatch(x->x.activityInfo.name.endsWith("ShareActivity")),"multiple-file share target registered");
        File directory=new File(context.getFilesDir(),"transfers");directory.mkdirs();String imageId=id(),fileId=id();File image=new File(directory,imageId+".test.png");Bitmap bitmap=Bitmap.createBitmap(4,4,Bitmap.Config.ARGB_8888);bitmap.eraseColor(0xff087f73);try(OutputStream output=new FileOutputStream(image)){bitmap.compress(Bitmap.CompressFormat.PNG,100,output);}bitmap.recycle();String hash=hex(MessageDigest.getInstance("SHA-256").digest(java.nio.file.Files.readAllBytes(image.toPath())));
        JSONArray paths=new JSONArray().put(a).put(b);JSONObject offer=new JSONObject().put("id",imageId).put("name","smoke.png").put("mime","image/png").put("kind","image").put("size",image.length()).put("hash",hash).put("chunks",1).put("expires",System.currentTimeMillis()/1000+3600).put("status","ready").put("sender",peer);JSONObject preview=new JSONObject().put("offer",offer).put("pairs",paths).put("phase","preview").put("path",image.getAbsolutePath()).put("sourcePair",a);
        JSONObject fileOffer=new JSONObject(offer.toString()).put("id",fileId).put("name","smoke.bin").put("kind","file");JSONObject waiting=new JSONObject().put("offer",fileOffer).put("pairs",paths).put("phase","waiting");call("attachment-save",new JSONObject().put("outgoing",new JSONArray()).put("incoming",new JSONArray().put(preview).put(waiting)).toString(),null);
        Activity main=launch("io.clipbridge.android.MainActivity",null);NotificationManager notifications=context.getSystemService(NotificationManager.class);await(()->Arrays.stream(notifications.getActiveNotifications()).anyMatch(n->n.getId()==4100));check(true,"foreground connected-device receiver starts with notification permission");await(()->Arrays.stream(notifications.getActiveNotifications()).anyMatch(n->n.getId()==nid(imageId)));Notification notification=Arrays.stream(notifications.getActiveNotifications()).filter(n->n.getId()==nid(imageId)).findFirst().orElseThrow().getNotification();check(notification.actions!=null&&notification.actions.length==2&&notification.extras.containsKey("android.picture"),"image notification contains preview and save/reject actions");
        notification.actions[0].actionIntent.send();await(()->item(imageId).optString("phase").equals("done"));JSONObject completed=item(imageId);Uri savedImage=Uri.parse(completed.getString("destination"));rows.add(savedImage);try(android.database.Cursor cursor=context.getContentResolver().query(savedImage,new String[]{MediaStore.MediaColumns.RELATIVE_PATH},null,null,null)){check(cursor!=null&&cursor.moveToFirst()&&cursor.getString(0).startsWith("Pictures/ClipBridge"),"accept image saves it to ClipBridge album");}
        await(()->Arrays.stream(notifications.getActiveNotifications()).anyMatch(n->n.getId()==nid(fileId)));Notification fileNotification=Arrays.stream(notifications.getActiveNotifications()).filter(n->n.getId()==nid(fileId)).findFirst().orElseThrow().getNotification();fileNotification.actions[1].actionIntent.send();await(()->item(fileId).optString("phase").equals("rejected"));check(!item(fileId).has("destination"),"declining a file does not create a download");
        Activity share=launch("io.clipbridge.android.ShareActivity",new Intent(Intent.ACTION_SEND).setType("image/png").putExtra(Intent.EXTRA_STREAM,savedImage).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION));java.lang.reflect.Field target=share.getClass().getDeclaredField("targets");target.setAccessible(true);Spinner spinner=(Spinner)target.get(share);check(spinner.getAdapter().getCount()==1,"share UI merges configs for the same confirmed device");
        java.lang.reflect.Field button=share.getClass().getDeclaredField("send");button.setAccessible(true);runOnMainSync(()->((Button)getField(share,"send")).performClick());await(()->new JSONObject(call("attachment-load",null,null).getString("state")).getJSONArray("outgoing").length()==1);JSONObject sent=new JSONObject(call("attachment-load",null,null).getString("state")).getJSONArray("outgoing").getJSONObject(0);check(sent.getJSONArray("pairs").length()==2&&sent.getJSONObject("offer").getString("kind").equals("image"),"sharing image creates one task with two fallback routes");
        ArrayList<Uri> multiple=new ArrayList<>();multiple.add(savedImage);multiple.add(savedImage);Activity files=launch("io.clipbridge.android.ShareActivity",new Intent(Intent.ACTION_SEND_MULTIPLE).setType("application/octet-stream").putParcelableArrayListExtra(Intent.EXTRA_STREAM,multiple).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION));runOnMainSync(()->{((CheckBox)getField(files,"asFile")).setChecked(true);((Button)getField(files,"send")).performClick();});await(()->new JSONObject(call("attachment-load",null,null).getString("state")).getJSONArray("outgoing").length()==3);JSONArray jobs=new JSONObject(call("attachment-load",null,null).getString("state")).getJSONArray("outgoing");check(jobs.getJSONObject(1).getJSONObject("offer").getString("kind").equals("file")&&jobs.getJSONObject(2).getJSONObject("offer").getString("kind").equals("file"),"multiple shared files remain separate consent requests");check(jobs.getJSONObject(1).getJSONObject("uploaded").length()==0&&jobs.getJSONObject(2).getJSONObject("uploaded").length()==0,"shared files wait for consent without uploading payload");
        ok=true;result.putString("stream",passed+" Android smoke checks passed.\n");
    }catch(Throwable e){result.putString("stream","FAIL "+e.getClass().getSimpleName()+": "+e.getMessage()+"\n");}finally{
        if(context!=null&&touched){context.stopService(new Intent().setClassName(context,"io.clipbridge.android.TransferService"));try{Thread.sleep(600);JSONObject current=new JSONObject(call("attachment-load",null,null).getString("state"));for(String key:new String[]{"outgoing","incoming"}){JSONArray list=current.getJSONArray(key);for(int i=0;i<list.length();i++){String path=list.getJSONObject(i).optString("path");if(path.startsWith(new File(context.getFilesDir(),"transfers").getAbsolutePath()+File.separator))new File(path).delete();}}if(previousState!=null)call("attachment-save",previousState,null);for(String pair:pairs)call("delete",pair,null);for(Uri row:rows)context.getContentResolver().delete(row,null,null);context.getSystemService(NotificationManager.class).cancelAll();}catch(Exception ignored){}for(Activity activity:activities)try{runOnMainSync(activity::finish);}catch(Exception ignored){}}
        finish(ok?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);
    }}
    private String hex(byte[] bytes){StringBuilder s=new StringBuilder();for(byte b:bytes)s.append(String.format(java.util.Locale.ROOT,"%02x",b&255));return s.toString();}
    private Object getField(Activity activity,String name){try{java.lang.reflect.Field field=activity.getClass().getDeclaredField(name);field.setAccessible(true);return field.get(activity);}catch(Exception e){throw new RuntimeException(e);}}
}
